questions.solution:
function findTasks(userId, filters) {
  const where = ["user_id = $1"];
  const values = [userId];
  if (typeof filters.done === "boolean") {
    values.push(filters.done);
    where.push(`done = $${values.length}`);
  }
  if (filters.q) {
    values.push(`%${filters.q}%`);
    where.push(`title ilike $${values.length}`);
  }
  return { text: `select * from tasks where ${where.join(" and ")} order by id`, values };
}

console.log(findTasks(1, {}));
console.log(findTasks(1, { done: false, q: "milk" }));

