const COLUMNS = { id: "id", title: "title", createdAt: "created_at" };

function orderBy(sort) {
  const name = sort.replace(/^-/, "");
  if (!Object.hasOwn(COLUMNS, name)) return null;
  const direction = sort.startsWith("-") ? " desc" : "";
  return `order by ${COLUMNS[name]}${direction}, id`;
}

console.log(orderBy("title"));
console.log(orderBy("-createdAt"));
console.log(orderBy("title; drop table tasks"));

