questions.solution:
function updateTask(userId, id, changes) {
  const sets = [];
  const values = [];
  for (const field of ["title", "done"]) {
    if (field in changes) {
      values.push(changes[field]);
      sets.push(`${field} = $${values.length}`);
    }
  }
  values.push(id, userId);
  const text = `update tasks set ${sets.join(", ")} where id = $${values.length - 1} and user_id = $${values.length} returning *`;
  return { text, values };
}

console.log(updateTask(1, 7, { done: true, user_id: 2 }));

