const tasks = [
  { id: 1, userId: 1, title: "Buy milk", done: false },
  { id: 2, userId: 2, title: "Fix bike", done: false },
];

function completeTask(userId, id) {
  const task = tasks.find((t) => t.id === id && t.userId === userId);
  if (!task) return null;
  task.done = true;
  return task;
}

console.log("user 1 tries task 2:", completeTask(1, 2));
console.log("user 2 tries task 2:", completeTask(2, 2));
console.log("user 1 tries task 9:", completeTask(1, 9));

